pub fn spawn_blocking<F, R>(f: F) ->  [JoinHandle](docs.rs/tokio/latest/tokio/task/struct.JoinHandle.html) <R>  ⓘ where
    F: [FnOnce](doc.rust-lang.org/nightly/core/ops/function/trait.FnOnce.html) () -> R + [Send](doc.rust-lang.org/nightly/core/marker/trait.Send.html) + 'static,
